import os
from google.cloud import documentai_v1beta3 as documentai
from google.cloud import translate_v3 as translate
from google.cloud import language_v1 as language
from google.cloud import aiplatform

class DocumentClient:
    def __init__(self, project_id: str, location: str = "us"):
        self.project_id = project_id
        self.location = location

    def get_documentai_client(self):
        return documentai.DocumentProcessorServiceClient()

    def get_translate_client(self):
        return translate.TranslationServiceClient()

    def get_language_client(self):
        return language.LanguageServiceClient()

    def get_vertex_ai_text_embedding_client(self):
        # Initialize Vertex AI for embeddings
        aiplatform.init(project=self.project_id, location=self.location)
        return aiplatform.gapic.PredictionServiceClient(
            client_options={"api_endpoint": f"{self.location}-aiplatform.googleapis.com"}
        )

# Helper to get project ID from environment or a default
def get_project_id():
    return os.environ.get("GCP_PROJECT_ID", "your-gcp-project-id")

from document_client import DocumentClient, get_project_id
from document_models import DocumentExtractionRequest, TableExtractionResponse
from google.cloud import documentai_v1beta3 as documentai

def extract_tables(request: DocumentExtractionRequest) -> TableExtractionResponse:
    project_id = get_project_id()
    doc_client_helper = DocumentClient(project_id=project_id, location=request.location)
    client = doc_client_helper.get_documentai_client()

    # Use a specific processor for table extraction, e.g., 'FORM_PARSER_PROCESSOR'
    # Replace with your actual processor ID if needed
    processor_id = request.processor_id or "your-table-processor-id"
    name = client.processor_path(project_id, request.location, processor_id)

    raw_document = documentai.RawDocument(
        content=request.document_bytes, mime_type=request.mime_type
    )
    process_options = documentai.ProcessOptions(ocr_config=documentai.OcrConfig(enable_native_pdf_parsing=True))

    try:
        response = client.process_document(
            name=name,
            raw_document=raw_document,
            process_options=process_options
        )
        document = response.document

        tables_data = []
        for page in document.pages:
            for table in page.tables:
                rows_data = []
                for row in table.body_rows:
                    cells_data = []
                    for cell in row.cells:
                        cells_data.append({"text": cell.text_anchor.content})
                    rows_data.append({"cells": cells_data})
                tables_data.append({"rows": rows_data})

        return TableExtractionResponse(tables=tables_data)

    except Exception as e:
        print(f"Error extracting tables: {e}")
        return TableExtractionResponse()

from document_client import DocumentClient, get_project_id
from document_models import DocumentExtractionRequest, KeyValueExtractionResponse
from google.cloud import documentai_v1beta3 as documentai

def extract_key_values(request: DocumentExtractionRequest) -> KeyValueExtractionResponse:
    project_id = get_project_id()
    doc_client_helper = DocumentClient(project_id=project_id, location=request.location)
    client = doc_client_helper.get_documentai_client()

    # Use a specific processor for key-value pair extraction, e.g., 'FORM_PARSER_PROCESSOR'
    # Replace with your actual processor ID if needed
    processor_id = request.processor_id or "your-key-value-processor-id"
    name = client.processor_path(project_id, request.location, processor_id)

    raw_document = documentai.RawDocument(
        content=request.document_bytes, mime_type=request.mime_type
    )
    process_options = documentai.ProcessOptions(ocr_config=documentai.OcrConfig(enable_native_pdf_parsing=True))

    try:
        response = client.process_document(
            name=name,
            raw_document=raw_document,
            process_options=process_options
        )
        document = response.document

        key_value_pairs = []
        for entity in document.entities:
            if entity.type_ == "form_field":
                key_value_pairs.append({
                    "field_name": entity.mention_text,
                    "field_value": entity.normalized_value.text if entity.normalized_value else entity.text_anchor.content
                })

        return KeyValueExtractionResponse(key_value_pairs=key_value_pairs)

    except Exception as e:
        print(f"Error extracting key-value pairs: {e}")
        return KeyValueExtractionResponse()

from document_client import DocumentClient, get_project_id
from document_models import TranslationRequest, TranslationResponse
from google.cloud import translate_v3 as translate

def ocr_translate(request: TranslationRequest) -> TranslationResponse:
    project_id = get_project_id()
    doc_client_helper = DocumentClient(project_id=project_id)
    client = doc_client_helper.get_translate_client()

    parent = f"projects/{project_id}/locations/global"

    try:
        response = client.translate_text(
            request=translate.TranslateTextRequest(
                parent=parent,
                contents=[request.text],
                target_language_code=request.target_language,
                source_language_code=request.source_language if request.source_language else None,
            )
        )
        translated_text = response.translations[0].translated_text if response.translations else ""
        return TranslationResponse(translated_text=translated_text)

    except Exception as e:
        print(f"Error translating text: {e}")
        return TranslationResponse(translated_text="")
